import * as http from 'node:http';
import * as https from 'node:https';
import { Readable } from 'node:stream';
import { createGzip } from 'node:zlib';
import type {
  BaseTransportOptions,
  Transport,
  TransportMakeRequestResponse,
  TransportRequest,
  TransportRequestExecutor,
} from '@sentry/core';
import { consoleSandbox, createTransport, suppressTracing } from '@sentry/core';
import { HttpsProxyAgent } from '../proxy';
import type { HTTPModule } from './http-module';

export interface NodeTransportOptions extends BaseTransportOptions {
  /**
   * Set a proxy that should be used for outbound requests.
   * Set to `false` to never use a proxy, even when `http_proxy` or `https_proxy` are set.
   */
  proxy?: string | false;
  /** HTTPS proxy CA certificates */
  caCerts?: string | Buffer | Array<string | Buffer>;
  /** Custom HTTP module. Defaults to the native 'http' and 'https' modules. */
  httpModule?: HTTPModule;
  /** Allow overriding connection keepAlive, defaults to true */
  keepAlive?: boolean;
}

// Estimated maximum size for reasonable standalone event
const GZIP_THRESHOLD = 1024 * 32;

/**
 * Gets a stream from a Uint8Array or string
 * Readable.from is ideal but was added in node.js v12.3.0 and v10.17.0
 */
function streamFromBody(body: Uint8Array | string): Readable {
  return new Readable({
    read() {
      this.push(body);
      this.push(null);
    },
  });
}

/**
 * Creates a Transport that uses native the native 'http' and 'https' modules to send events to Sentry.
 */
export function makeNodeTransport(options: NodeTransportOptions): Transport {
  let urlSegments: URL;

  try {
    urlSegments = new URL(options.url);
  } catch {
    consoleSandbox(() => {
      // eslint-disable-next-line no-console
      console.warn(
        '[@sentry/node]: Invalid dsn or tunnel option, will not send any events. The tunnel option must be a full URL when used.',
      );
    });
    return createTransport(options, () => Promise.resolve({}));
  }

  const isHttps = urlSegments.protocol === 'https:';

  const nativeHttpModule = isHttps ? https : http;
  const agent = getHttpAgent(urlSegments, { proxy: options.proxy, keepAlive: options.keepAlive });

  const requestExecutor = createRequestExecutor(options, options.httpModule ?? nativeHttpModule, agent);
  return createTransport(options, requestExecutor);
}

/**
 * Returns the agent for requests to `url`: a proxy agent when a proxy applies, otherwise a plain keep-alive agent.
 *
 * Proxy prioritization: http => `options.proxy` | `process.env.http_proxy`
 * Proxy prioritization: https => `options.proxy` | `process.env.https_proxy` | `process.env.http_proxy`
 * Hosts listed in `process.env.no_proxy` are never proxied, and `options.proxy: false` disables proxying entirely.
 */
export function getHttpAgent(url: URL, options: { proxy?: string | false; keepAlive?: boolean } = {}): http.Agent {
  const isHttps = url.protocol === 'https:';
  const proxy =
    options.proxy === false
      ? undefined
      : applyNoProxyOption(
          url,
          options.proxy || (isHttps ? process.env.https_proxy : undefined) || process.env.http_proxy,
        );

  if (proxy) {
    return new HttpsProxyAgent(proxy);
  }

  return new (isHttps ? https : http).Agent({ keepAlive: options.keepAlive ?? true, maxSockets: 30, timeout: 2000 });
}

/**
 * Honors the `no_proxy` env variable with the highest priority to allow for hosts exclusion.
 *
 * @param transportUrl The URL the transport intends to send events to.
 * @param proxy The client configured proxy.
 * @returns A proxy the transport should use.
 */
function applyNoProxyOption(transportUrlSegments: URL, proxy: string | undefined): string | undefined {
  const { no_proxy } = process.env;

  const urlIsExemptFromProxy = no_proxy
    ?.split(',')
    .some(
      exemption => transportUrlSegments.host.endsWith(exemption) || transportUrlSegments.hostname.endsWith(exemption),
    );

  if (urlIsExemptFromProxy) {
    return undefined;
  } else {
    return proxy;
  }
}

/**
 * Creates a RequestExecutor to be used with `createTransport`.
 */
function createRequestExecutor(
  options: NodeTransportOptions,
  httpModule: HTTPModule,
  agent: http.Agent,
): TransportRequestExecutor {
  const { hostname, pathname, port, protocol, search } = new URL(options.url);
  return function makeRequest(request: TransportRequest): Promise<TransportMakeRequestResponse> {
    const sendRequest = (canRetry: boolean): Promise<TransportMakeRequestResponse> =>
      new Promise((resolve, reject) => {
        // This ensures we do not generate any spans in OpenTelemetry for the transport
        suppressTracing(() => {
          // Recreate the body on each attempt so a retry is not piping a consumed stream.
          let body = streamFromBody(request.body);

          const headers: Record<string, string> = { ...options.headers };

          if (request.body.length > GZIP_THRESHOLD) {
            headers['content-encoding'] = 'gzip';
            body = body.pipe(createGzip());
          }

          const hostnameIsIPv6 = hostname.startsWith('[');

          const req = httpModule.request(
            {
              method: 'POST',
              agent,
              headers,
              // Remove "[" and "]" from IPv6 hostnames
              hostname: hostnameIsIPv6 ? hostname.slice(1, -1) : hostname,
              path: `${pathname}${search}`,
              port,
              protocol,
              ca: options.caCerts,
            },
            res => {
              res.on('data', () => {
                // Drain socket
              });

              res.on('end', () => {
                // Drain socket
              });

              res.setEncoding('utf8');

              // "Key-value pairs of header names and values. Header names are lower-cased."
              // https://nodejs.org/api/http.html#http_message_headers
              const retryAfterHeader = res.headers['retry-after'] ?? null;
              const rateLimitsHeader = res.headers['x-sentry-rate-limits'] ?? null;

              resolve({
                statusCode: res.statusCode,
                headers: {
                  'retry-after': retryAfterHeader,
                  'x-sentry-rate-limits': Array.isArray(rateLimitsHeader)
                    ? rateLimitsHeader[0] || null
                    : rateLimitsHeader,
                },
              });
            },
          );

          req.on('error', error => {
            // Keep-alive sockets can go stale while a serverless isolate is frozen.
            // Node recommends a single retry when the reused socket resets.
            if (canRetry && req.reusedSocket && (error as NodeJS.ErrnoException).code === 'ECONNRESET') {
              resolve(sendRequest(false));
            } else {
              reject(error);
            }
          });
          body.pipe(req);
        });
      });

    return sendRequest(true);
  };
}
